import{_ as t,o as e,c as s,a5 as d}from"./chunks/framework.CslsFoWx.js";const b=JSON.parse('{"title":"Canaux clients (menu QR, commande en ligne, click & collect)","description":"","frontmatter":{"pageClass":"wide","aside":false},"headers":[],"relativePath":"modules/16-customer-channels.md","filePath":"generated/modules/16-customer-channels.md","lastUpdated":null}'),n={name:"modules/16-customer-channels.md"};function r(i,a,o,l,p,c){return e(),s("div",null,[...a[0]||(a[0]=[d('<h1 id="canaux-clients-menu-qr-commande-en-ligne-click-collect" tabindex="-1">Canaux clients (menu QR, commande en ligne, click &amp; collect) <a class="header-anchor" href="#canaux-clients-menu-qr-commande-en-ligne-click-collect" aria-label="Permalink to &quot;Canaux clients (menu QR, commande en ligne, click &amp; collect)&quot;">​</a></h1><p><span class="badge todo">À faire</span> <span class="muted">Phase 4 · <a href="/VendoraSystem-docs/specs/16-customer-channels">spécification complète</a></span></p><p>Menu QR à table, commande depuis le téléphone du client et click &amp; collect, servis par le cloud comme exception documentée au principe offline-first, avec garde-fous anti-abus et confirmation du magasin. Aucun canal client n&#39;est encore implémenté (phase 4) ; le socle réutilisé est en place : addition standard routée vers les postes et le KDS (spec 08), interface PaymentProvider avec connecteurs simulés et webhooks signés (spec 03), thème magasin / marque (spec 13).</p><div class="kpis"><div><b>3</b><span>faites</span></div><div><b>7</b><span>partielles</span></div><div><b>15</b><span>à faire</span></div><div><b>0</b><span>bloquées</span></div></div><h2 id="socle-reutilise" tabindex="-1">Socle réutilisé <a class="header-anchor" href="#socle-reutilise" aria-label="Permalink to &quot;Socle réutilisé&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Commande standard routée en cuisine</strong><br><span class="muted">Traiter une commande client comme une addition ordinaire : envois numérotés, états des lignes, routage par poste vers KDS et imprimantes, convergence d&#39;une même table.<br><i>Socle de la spec 08 livré ; les canaux QR_TABLE / ONLINE et l&#39;entrée des commandes par le cloud ne sont pas branchés (phase 4).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CHAN-03</td><td>2.2, 2.4, 2.5, 2.11, 2.12</td><td><a href="/VendoraSystem-docs/preuves/2026-10-29-addition-table">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-bons-cuisine">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-29-ecran-cuisine">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-convergence-table">📷</a></td></tr><tr><td><strong>Interface PaymentProvider et webhooks signés</strong><br><span class="muted">S&#39;appuyer sur la couche de paiement pluggable (intents, statut, confirmation par relecture ou webhook signé HMAC, remboursement) et ses connecteurs Flouci / Konnect / Paymee / TPE simulés par magasin.<br><i>Passerelles HTTP réelles (clés sandbox = actions terrain), intents initiés depuis une PWA, pré-autorisation / capture différée et remboursement réel (503 hors MOCK) non faits.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge ok">Fait</span></td><td>RG-CHAN-11, RG-CHAN-13</td><td>2.10, 2.16, 2.23</td><td><a href="/VendoraSystem-docs/preuves/2026-10-30-paiement-fournisseur">📷</a> <a href="/VendoraSystem-docs/preuves/2026-10-30-connecteurs-paiement">📷</a></td></tr></tbody></table><h2 id="canaux-activation" tabindex="-1">Canaux &amp; activation <a class="header-anchor" href="#canaux-activation" aria-label="Permalink to &quot;Canaux &amp; activation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Configuration des canaux par magasin</strong><br><span class="muted">Activer indépendamment la consultation du menu, la commande à table et le click &amp; collect, et régler paiements, plafonds, confirmation, politique hors ligne et créneaux.<br><i>Vague A : réglages par magasin (menu, à table, à emporter, plafonds, confirmation, hors ligne), option « Menu QR et commande en ligne » ; les canaux de commande s&#39;appliquent aux vagues B et C. À emporter refusé en France (TVA à emporter non gérée).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CHAN-02, RG-CHAN-20, RG-CHAN-21</td><td>4.2</td><td><a href="/VendoraSystem-docs/preuves/2026-11-13-4.2-vA">📷</a></td></tr><tr><td><strong>Canaux QR_TABLE et ONLINE</strong><br><span class="muted">Étendre le canal des commandes aux valeurs QR_TABLE (à table) et ONLINE (à emporter), badgées sur les bons et le KDS.<br><i>Phase 4 — dépend aussi du canal KIOSK de la spec 09.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-CHAN-01, RG-CHAN-03</td><td></td><td></td></tr></tbody></table><h2 id="menu-public" tabindex="-1">Menu public <a class="header-anchor" href="#menu-public" aria-label="Permalink to &quot;Menu public&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Menu web mobile (PWA)</strong><br><span class="muted">Ouvrir sans authentification un menu mobile aux couleurs du magasin (logo, couleurs, langue, devise), avec photos, descriptions et prix TTC, en moins de 3 s.<br><i>Menu web mobile /m/&lt;jeton&gt; au thème du magasin, FR / EN / AR (RTL), 179 Ko au premier chargement, Lighthouse 4G lente &lt; 3 s ; pas encore installable (PWA) ni commandable (vague B).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CHAN-04, RG-CHAN-06</td><td>4.2</td><td><a href="/VendoraSystem-docs/preuves/2026-11-13-4.2-vA">📷</a></td></tr><tr><td><strong>Produits publiés en ligne</strong><br><span class="muted">Choisir au back-office (à l&#39;unité ou en masse) les produits visibles en ligne, opt-in par défaut, avec aperçu du menu.<br><i>Case « Visible en ligne » unitaire et en masse, faux par défaut ; 14 allergènes ; produits à variantes pas encore proposés en ligne.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CHAN-05</td><td>4.2</td><td><a href="/VendoraSystem-docs/preuves/2026-11-13-4.2-vA">📷</a></td></tr><tr><td><strong>Ruptures masquées en temps réel</strong><br><span class="muted">Masquer du menu un produit en rupture (« 86 ») et refuser à l&#39;envoi une ligne devenue indisponible, le reste du panier étant conservé.<br><i>Surcharge « indisponible » du magasin et, si activé, stock nul masquent le produit ; le menu relit la disponibilité toutes les 30 s. Le « 86 » depuis la caisse viendra plus tard.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CHAN-05, RG-CHAN-41</td><td>4.2</td><td><a href="/VendoraSystem-docs/preuves/2026-11-13-4.2-vA">📷</a></td></tr><tr><td><strong>Modificateurs sur le menu</strong><br><span class="muted">Choisir les options d&#39;un plat avec les mêmes contraintes min / max qu&#39;en caisse : un groupe obligatoire non renseigné bloque l&#39;ajout au panier.<br><i>Groupes de modificateurs affichés sur le menu ; leur choix et leur revalidation viennent avec la commande (vague B).</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CHAN-06</td><td>4.2</td><td><a href="/VendoraSystem-docs/preuves/2026-11-13-4.2-vA">📷</a></td></tr></tbody></table><h2 id="qr-securite" tabindex="-1">QR &amp; sécurité <a class="header-anchor" href="#qr-securite" aria-label="Permalink to &quot;QR &amp; sécurité&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>QR codes de table et de menu</strong><br><span class="muted">Générer au back-office un QR par table (planche PDF A4 et étiquette unitaire) et un QR de menu seul pour le comptoir et la vitrine.<br><i>Planche PDF A4 (une étiquette par table + QR « menu seul ») et étiquette unitaire, dans la langue du magasin (arabe compris) ; adresse par POS_MENU_URL, sans domaine de production figé.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CHAN-07</td><td>4.2</td><td><a href="/VendoraSystem-docs/preuves/2026-11-13-4.2-vA">📷</a></td></tr><tr><td><strong>Révocation et régénération des QR</strong><br><span class="muted">Régénérer un QR (MANAGER+, tracé) pour invalider immédiatement l&#39;ancien ; un token révoqué ou inconnu répond 404 sans révéler le magasin.<br><i>Régénération du QR d&#39;une table et du lien du menu, tracées à l&#39;audit ; un ancien jeton répond 404 comme un jeton inconnu.</i></span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge ok">Fait</span></td><td>RG-CHAN-08, RG-CHAN-20</td><td>4.2</td><td><a href="/VendoraSystem-docs/preuves/2026-11-13-4.2-vA">📷</a></td></tr><tr><td><strong>Limitation de débit et revalidation serveur</strong><br><span class="muted">Limiter le débit des endpoints publics (session, IP, token ; 429) et revalider montants et quantités par le moteur de calcul partagé — le panier du navigateur n&#39;est jamais une source de vérité.<br><i>Limites de débit des pages publiques (session, réseau, /32 IPv6, jeton du menu avec part équitable, budget propre des images) ; la revalidation des commandes par le moteur partagé vient en vague B.</i></span></td><td><span class="badge partial">Partiel</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge ok">Fait</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-CHAN-09, RG-CHAN-34</td><td>4.2</td><td><a href="/VendoraSystem-docs/preuves/2026-11-13-4.2-vA">📷</a></td></tr></tbody></table><h2 id="commande-a-table" tabindex="-1">Commande à table <a class="header-anchor" href="#commande-a-table" aria-label="Permalink to &quot;Commande à table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Commande depuis le téléphone à table</strong><br><span class="muted">Envoyer un panier depuis le QR de la table : ajouté comme nouvel envoi sur l&#39;addition ouverte, sinon nouvelle addition QR_TABLE, routée en cuisine comme un envoi serveur.<br><i>Phase 4.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-CHAN-10</td><td></td><td></td></tr><tr><td><strong>Notification du serveur de salle</strong><br><span class="muted">Prévenir le serveur de la table (ou toutes les caisses en repli) de l&#39;arrivée d&#39;une commande client.<br><i>Phase 4 — aucune notification push n&#39;existe encore (avis à l&#39;écran seulement, lot 2.5).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-CHAN-10</td><td></td><td></td></tr><tr><td><strong>Paiement de l&#39;addition depuis le téléphone</strong><br><span class="muted">Régler tout ou partie de l&#39;addition via un fournisseur de paiement depuis le téléphone, ou garder l&#39;addition classique encaissée par le personnel.<br><i>Phase 4 — dépend des vrais connecteurs de paiement.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-CHAN-11</td><td></td><td></td></tr></tbody></table><h2 id="click-collect" tabindex="-1">Click &amp; collect <a class="header-anchor" href="#click-collect" aria-label="Permalink to &quot;Click &amp; collect&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Créneaux de retrait</strong><br><span class="muted">Choisir un créneau ouvert (capacité, délai de préparation) ou « au plus tôt » ; un créneau complet propose les suivants.<br><i>Phase 4.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td>RG-CHAN-12, RG-CHAN-18</td><td></td><td></td></tr><tr><td><strong>Numéro de retrait W-</strong><br><span class="muted">Recevoir un numéro de retrait court préfixé W- (séquence journalière allouée par le cloud) et le retrouver à la caisse pour l&#39;encaissement au comptoir.<br><i>Phase 4 — les numéros séquentiels de la spec 09 restent ouverts (reste du lot 2.6).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-CHAN-12, RG-CHAN-13</td><td></td><td></td></tr><tr><td><strong>Paiement en ligne ou au comptoir</strong><br><span class="muted">Payer en ligne (départ en cuisine au paiement) ou au comptoir au retrait, avec liaison commande → vente.<br><i>Phase 4.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-CHAN-13</td><td></td><td></td></tr><tr><td><strong>Page de suivi de commande</strong><br><span class="muted">Suivre l&#39;état réel de sa commande (en attente de confirmation, reçue, en préparation, prête) sur la page de confirmation.<br><i>Phase 4.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td>RG-CHAN-13, RG-CHAN-18</td><td></td><td></td></tr></tbody></table><h2 id="anti-abus-confirmation" tabindex="-1">Anti-abus &amp; confirmation <a class="header-anchor" href="#anti-abus-confirmation" aria-label="Permalink to &quot;Anti-abus &amp; confirmation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Plafonds anti-abus</strong><br><span class="muted">Refuser au-delà du montant maximal, du nombre de commandes actives par session ou par table, et bloquer les sessions abusives, visibles au back-office.<br><i>Phase 4.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td>RG-CHAN-14</td><td></td><td></td></tr><tr><td><strong>Confirmation du magasin</strong><br><span class="muted">Accepter ou refuser (avec motif) une commande en attente depuis la caisse ou le back-office, avec expiration après un délai et remboursement automatique si déjà payée.<br><i>Phase 4.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-CHAN-15, RG-CHAN-20</td><td></td><td></td></tr></tbody></table><h2 id="cote-magasin" tabindex="-1">Côté magasin <a class="header-anchor" href="#cote-magasin" aria-label="Permalink to &quot;Côté magasin&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>File « Commandes en ligne » sur la caisse</strong><br><span class="muted">Voir sur la caisse les commandes en ligne (numéro, créneau, payée / à encaisser) avec Accepter / Refuser, et les bons badgés QR TABLE / EN LIGNE en cuisine.<br><i>Phase 4.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td>RG-CHAN-03, RG-CHAN-15</td><td></td><td></td></tr></tbody></table><h2 id="exception-offline-first" tabindex="-1">Exception offline-first <a class="header-anchor" href="#exception-offline-first" aria-label="Permalink to &quot;Exception offline-first&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Appareil virtuel ONLINE_GATEWAY</strong><br><span class="muted">Faire entrer les commandes cloud par le flux de synchronisation standard, signées par un appareil virtuel propre à chaque magasin et limité aux événements du module.<br><i>Phase 4 — un appareil virtuel BACKOFFICE émet déjà les événements de configuration (phase 1).</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td>RG-CHAN-16</td><td></td><td></td></tr><tr><td><strong>File cloud quand le magasin est hors ligne</strong><br><span class="muted">Mettre en file côté cloud les commandes ONLINE (QUEUE) ou désactiver la commande avec un avertissement (BLOCK), livrer la file dans l&#39;ordre et sans doublon à la reconnexion, annuler et rembourser à expiration.<br><i>Phase 4.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge todo">À faire</span></td><td>RG-CHAN-17, RG-CHAN-18</td><td></td><td></td></tr><tr><td><strong>Supervision de la file cloud</strong><br><span class="muted">Suivre au back-office les commandes en attente de livraison au magasin (état, ancienneté, TTL) et être alerté si la file ne se vide pas.<br><i>Phase 4.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td>RG-CHAN-17</td><td></td><td></td></tr></tbody></table><h2 id="supervision" tabindex="-1">Supervision <a class="header-anchor" href="#supervision" aria-label="Permalink to &quot;Supervision&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Fonctionnalité</th><th>Statut</th><th>Partagé</th><th>Serveur</th><th>Android</th><th>iOS</th><th>Web</th><th>Règles</th><th>Lots</th><th>Preuve</th></tr></thead><tbody><tr><td><strong>Statistiques par canal</strong><br><span class="muted">Consulter les volumes, paniers moyens et taux de refus / expiration par canal.<br><i>Phase 4 — restitution via les rapports de la spec 12.</i></span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td><span class="badge na">—</span></td><td><span class="badge na">—</span></td><td><span class="badge todo">À faire</span></td><td></td><td></td><td></td></tr></tbody></table><h2 id="reste-a-faire" tabindex="-1">Reste à faire <a class="header-anchor" href="#reste-a-faire" aria-label="Permalink to &quot;Reste à faire&quot;">​</a></h2><ul><li>ChannelConfig par magasin et nouveaux canaux QR_TABLE / ONLINE.</li><li>Menu web mobile (PWA) thémé, publication opt-in des produits, ruptures en temps réel, modificateurs.</li><li>QR de table et de menu imprimables, révocation des tokens, limitation de débit et revalidation par le moteur partagé.</li><li>Commande à table rattachée à l&#39;addition ouverte, notification du serveur, paiement à table via fournisseur.</li><li>Click &amp; collect : créneaux, numéro W-, paiement en ligne ou au comptoir, page de suivi client.</li><li>Plafonds anti-abus et confirmation du magasin (accepter / refuser, expiration, remboursement).</li><li>Appareil virtuel ONLINE_GATEWAY, file cloud QUEUE / BLOCK et supervision au back-office.</li><li>Prérequis à lever : vraies passerelles de paiement (actions terrain), numéros séquentiels de la spec 09, notifications push.</li></ul>',26)])])}const h=t(n,[["render",r]]);export{b as __pageData,h as default};
